# This could lead to larger expansions
import re

# Build a map of compat decompositions
compat_map = {}
with open('/workspace/repo-vul/src-vul/krb5/src/lib/krb5/unicode/UnicodeData.txt') as f:
    for line in f:
        parts = line.strip().split(';')
        if len(parts) < 6:
            continue
        cp = int(parts[0], 16)
        decomp = parts[5]
        if '<compat>' in decomp:
            decomp_cps = [int(x, 16) for x in decomp.replace('<compat>', '').strip().split()]
            compat_map[cp] = decomp_cps

# Recursively expand
def expand(cp, depth=0):
    if depth > 5:
        return [cp]
    if cp in compat_map:
        result = []
        for d in compat_map[cp]:
            result.extend(expand(d, depth+1))
        return result
    return [cp]

# Find chars with large expansion
results = []
for cp in compat_map:
    expanded = expand(cp)
    if all(c < 0x80 for c in expanded):
        if cp < 0x80:
            utf8_len = 1
        elif cp < 0x800:
            utf8_len = 2
        elif cp < 0x10000:
            utf8_len = 3
        else:
            utf8_len = 4
        expansion = len(expanded) - utf8_len
        if expansion > 1:
            results.append((expansion, cp, utf8_len, len(expanded), expanded))

results.sort(reverse=True)
for r in results[:20]:
    expansion, cp, utf8_len, num_decomp, decomp_cps = r
    print(f'U+{cp:04X}: UTF8={utf8_len}B, decomp={num_decomp} ASCII, expansion={expansion}: {[chr(c) for c in decomp_cps]}')
